import{_ as e,o as t,c as r,ae as n}from"./chunks/framework.BX6FPmO9.js";const h=JSON.parse('{"title":"ADR：Spec-driven 契約與單一來源（SoT）","description":"","frontmatter":{},"headers":[],"relativePath":"adr/spec-driven-contracts-and-sot.md","filePath":"adr/spec-driven-contracts-and-sot.md"}'),a={name:"adr/spec-driven-contracts-and-sot.md"};function s(c,o,d,i,p,l){return t(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="adr-spec-driven-契約與單一來源-sot" tabindex="-1">ADR：Spec-driven 契約與單一來源（SoT） <a class="header-anchor" href="#adr-spec-driven-契約與單一來源-sot" aria-label="Permalink to &quot;ADR：Spec-driven 契約與單一來源（SoT）&quot;">​</a></h1><p><strong>狀態</strong>：Accepted（演進中）<br><strong>日期</strong>：2026-04-09</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>前後端分屬不同 deployable，但採 <strong>monorepo</strong> 以降低 spec／契約同步成本。先前 <code>backend</code> 曾手抄 Zod，違反單一真實來源。</p><h2 id="決策" tabindex="-1">決策 <a class="header-anchor" href="#決策" aria-label="Permalink to &quot;決策&quot;">​</a></h2><ol><li><strong>契約程式</strong>集中在 <strong><code>packages/shared-contracts</code></strong>（npm：<code>@ai-search-portal/contracts</code>），Remix <code>app/shared/contracts/index.ts</code> <strong>僅 re-export</strong>，不得新增 <code>*.contract.ts</code>。</li><li><strong>Import 邊界</strong>：<code>app/**</code> 與 <code>backend/**</code> <strong>不得</strong>互相 import；API 形狀僅能經 <code>@ai-search-portal/contracts</code>。</li><li><strong>過渡期（階段一～二）</strong>：Zod 為程式層 SoT；<strong><code>specs/openapi/</code></strong> 與 Zod <strong>雙軌對齊</strong>，OpenAPI 暫非唯一強制來源；變更順序為 <strong>先 Zod，後 OpenAPI + codegen</strong>。</li><li><strong>切換後（另開 ADR 宣告）</strong>：HTTP SoT 改為 OpenAPI；<code>shared-contracts</code> 以 <strong>generated</strong> 為主。</li><li><strong>下一決策點</strong>：OpenAPI 完全取代 Zod 作為來源 <strong>vs</strong> Zod 為 runtime 來源並由工具產出 OpenAPI——待切換前決定。</li></ol><h2 id="後果" tabindex="-1">後果 <a class="header-anchor" href="#後果" aria-label="Permalink to &quot;後果&quot;">​</a></h2><ul><li>需維護 <code>pnpm run codegen:openapi</code> 與 CI diff，避免 spec 與產物漂移。</li><li>Remix／Vite 與 backend 建置前須 <strong><code>build:contracts</code></strong>（含 codegen）。</li></ul>',8)])])}const m=e(a,[["render",s]]);export{h as __pageData,m as default};
